function productFeit(i) { const f = PRODUCTFEITEN[i.id]; return f ? `<p><b>Winkelgegevens, gecontroleerd ${e(f.gecontroleerd || '6 november 2026')}:</b> ${e(f.feit)} <a href="https://kadoly.com/product/${e(i.id)}">Bekijk de productspecificatie</a>.</p><p><b>Let op:</b> ${e(f.let)} Geen eigen gebruiks- of laboratoriumtest. Nieuwe productspecificaties kunnen deze gegevens wijzigen.</p>` : ''; }
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function onderzoekVoor(i) { return i?.t ? ONDERZOEK.filter(p => p.match(i)) : []; }
export function dekking(items) { const actief = items.filter(i => i && i.vr !== false); return { versie: ONDERZOEK_DAG, totaal: actief.length, metCategorieAdvies: actief.filter(i => onderzoekVoor(i).length).length, exactModelGetest: 0, onderwerpen: ONDERZOEK.map(p => ({ id: p.id, titel: p.titel, producten: actief.filter(p.match).length })) }; }
export function bronLink(i) { if (i?.id === 'dp_1019') return '<p class="meta"><a href="/onderzoek-en-bronnen#kamado-22nov">Kamado-koopcheck: uitvoering, vrachtwagenlevering en alleen buiten gebruiken</a> · makerinstructie en GGD-advies, geen modeltest</p>'; if (i?.id==='oc_4174005507588097' || i?.id!=='oc_4174005507129345' && /baby\s*slaapzak|babyslaapzak/i.test(i?.t || '')) return '<p class="meta"><a href="/onderzoek-en-bronnen#instroom-21nov">Babyslaapzakcheck: warmte, pasvorm en sluiting controleren</a> · categorieadvies, geen modeltest</p>'; if (['dp_1091','dp_1160','dp_1187','dp_1188','dp_1222','dp_1074'].includes(i?.id)) return '<p class="meta"><a href="/onderzoek-en-bronnen#instroom-21nov">Koopcheck: bedoeld gebruik, onderdelen en beperkingen</a> · makergegevens, geen modeltest</p>'; if (['dp_1021','dp_1027','dp_1035','dp_1037'].includes(i?.id)) return '<p class="meta"><a href="/onderzoek-en-bronnen#meubels-20nov">Meubelcheck: variant, levering en montage bevestigen</a> · makergegevens, geen modeltest</p>'; if (['dp_1010','dp_1013','dp_1017'].includes(i?.id)) return '<p class="meta"><a href="/onderzoek-en-bronnen#instroom-19nov">Hanglampcheck: fitting, licht en levering eerst bevestigen</a> · makerinformatie, geen modeltest</p>'; const nieuw = nieuwProductAdvies(i); if (nieuw) return nieuw; if (i?.id === 'oc_4173957651300353') return '<p class="meta"><strong>Prijs en variant niet bevestigd:</strong> op 15 november 2026 verschilde de catalogusprijs van de productpagina. <a href="/houten-bureau-accessoires#zo-kozen-we">Lees de beperking</a>; bevestig prijs en variant vóór bestellen.</p>'; const p = onderzoekVoor(i)[0]; if (p) return `<p class="meta" style="margin:5px 10px 14px"><a href="/onderzoek-${p.id}#p-${e(i.id)}">Koopcheck: ${e(p.titel)}</a> · algemene bron, geen producttest</p>`;
  if (i?.t && /whisk(e)?y|tumbler/i.test(i.t) && !/polijst|sieraad|rotatie|machine|kaars|geur/i.test(i.t)) return '<p class="meta"><a href="/whisky-set-cadeau#zo-kozen-we">Koopcheck drinkglazen en karaffen: materiaal en gebruik</a> · categorieadvies, geen producttest</p>';
  // Eigen, kritische gids voor deze constructievraag; geen negende onderzoeksprofiel of exact-modeltest.
  return i?.t && /tafel\s*haard|bio[ -]?ethanol|vuurpot/i.test(i.t) && !/vuurschaal/i.test(i.t) ? '<p class="meta" style="margin:5px 10px 14px"><a href="/tafelhaard">Koopcheck tafelhaard: emissies en branderconstructie</a> · categorieadvies, geen producttest</p>' : ''; }
export function bronnenHtml(ids, gecontroleerd) { return `<ol>${ids.map(id => { const b = BRONNEN[id]; return `<li><a href="${e(b.url)}" rel="noopener">${e(b.titel)}</a>. ${e(b.organisatie)}. ${e(b.soort)}${b.datum ? ', gepubliceerd ' + e(b.datum) : ', publicatiedatum niet vastgesteld'}. Gecontroleerd ${e(gecontroleerd || b.gecontroleerd || '2026-11-04')}.<p class="meta">${e(b.grens)}</p></li>`; }).join('')}</ol>`; }
export function adviesBlok(items) { const profielen = ONDERZOEK.filter(p => items.some(p.match)); if (!profielen.length) return ''; return `<section id="bronadvies"><h2>Wat zeggen andere bronnen?</h2><p>Wij zijn de verkoper. Dit is ons redactionele advies op basis van externe bronnen, geen onafhankelijke test van deze producten.</p>${profielen.map(p => `<details class="faq"><summary>${e(p.titel)}</summary><div class="a"><p>${e(p.kort)}</p><p>${e(p.nuance)}</p><p><a href="/onderzoek-${p.id}">Bekijk onderzoek, beperkingen en producten</a></p>${bronnenHtml(p.bronnen)}</div></details>`).join('')}</section>`; }

