function nieuwProductBronnen(items) {
  const beschikbaar = id => items.some(i=>i?.id===id&&i.vr!==false) ? 'In de huidige gidscatalogus beschikbaar.' : 'Momenteel niet beschikbaar in de gidscatalogus; controleer de winkel.';
  return '<section id="nieuw-productadvies"><h2>Nieuwe babyproducten en broches: eerst controleren</h2><p class="meta">Productgegevens gecontroleerd 18 november 2026. Aanvullend redactioneel advies buiten de acht thematellingen, geen eigen producttest.</p><h3>Gevlochten bedbumper van Nordic Coast Company</h3><p><strong>Wij raden dit product af voor het babybed.</strong> VeiligheidNL en NIH adviseren zachte bedomranders weg te laten. De winkelclaim dat deze bumper de veiligheid verbetert is hiermee in strijd; voor de genoemde ontwikkelingswinst is geen onderbouwing ingezien. Dit is categorieadvies, geen test of terugroepactie van dit model.</p><p>De winkel noemt circa 200 cm, katoen, wassen op 30 graden en OEKO-TEX/CE. Certificaatnummers, scope en veiligheidsrapporten zijn niet gecontroleerd; die vermeldingen bevestigen hier geen veilig slaapgebruik. '+e(leveringsBeperking({id:'oc_4174005539848193'}))+' '+beschikbaar('oc_4174005539848193')+'</p><h3>Grijze babyslaapzak met fleecevoering</h3><p>De maker noemt katoen met polyester-fleecevulling, maten 60 tot 110 cm, een YKK-rits en vier schouderdrukkers. TOG ontbreekt in de gecontroleerde tekst. Een slaapzak kan passend beddengoed zijn, maar deze informatie bewijst geen geschiktheid voor koude én warme nachten.</p><p>VeiligheidNL benadrukt passende hals- en armsgaten, vrije armen en een geschikte sluiting. Controleer ook de warmte voor kamer en kleding; alleen lichaamslengte plus 10 tot 15 cm is geen volledige pasvormcontrole. Vraag de uitvoering en warmte-instructie op. Onbekende TOG betekent niet automatisch slechte kwaliteit. '+beschikbaar('oc_4174005507129345')+'</p><h3>Kolibri-broches van by Vivi.</h3><p>Handwerk, kwaliteit en bijna 100 stijlen zijn makeropgaven, geen onafhankelijke test of bevestigde variantkeuze bij deze prijs. Materiaal, afmetingen, sluiting en exact aantal geleverde broches zijn niet in de gecontroleerde tekst vastgesteld. Bevestig die vóór aankoop. '+beschikbaar('oc_4174005944942593')+'</p><p>Gecontroleerde winkelpagina’s: <a href="https://kadoly.com/product/bettschlange-geflochten-rosa-jersey?lang=nl">bedbumper</a>, <a href="https://kadoly.com/product/grey-baby-sleeping-bag?lang=nl">slaapzak</a>, <a href="https://kadoly.com/product/broschenpaar-kolibri?lang=nl">broches</a>.</p><h3>Bronnen en beperkingen</h3>'+bronnenHtml(['babyBumper','babySlaapzak','babyNih'])+'<p>Wij zijn de verkoper. We hebben de producten niet gebruikt of getest en vragen geen aankoop om dit advies te lezen. <a href="/alle-producten">Volledig aanbod en actuele catalogusprijzen</a>.</p></section>';
}

function instroom19(items) {
 return '<section id="instroom-19nov"><h2>Nieuwe theeset, glazen en hanglampen: wat ontbreekt?</h2><p class="meta">Winkelgegevens en externe voorlichting gecontroleerd 19 november 2026. Wij zijn de verkoper; geen eigen montage of modeltest.</p><h3>Nina en Lauren: gebruiksinstructie gaat voor materiaalnaam</h3><p>Nina bevat een theepot van 900 ml, melkkan en suikerpot, geen genoemde kopjes. De winkel noemt porselein met roestvrijstalen accenten; magnetron, oven en vaatwasser zijn niet bevestigd. Lauren bestaat uit zes dubbelwandige glazen van 490 ml. Warm/koud en vaatwasserbestendig zijn winkelclaims, geen ingeziene thermische test. Vraag de temperatuurgrens en onderhoudsinstructie na. De NVWA waarschuwt voor thermische schokken bij thee- en koffieglazen; dit is geen aanwijzing dat Lauren onveilig is.</p><p><a href="/onderzoek-servies-gebruik#p-dp_1004">Nina: feiten en koopcheck</a> · <a href="/onderzoek-servies-gebruik#p-dp_1007">Lauren: feiten en koopcheck</a></p><h3>Sky, Dome en Whipped: is de fitting inbegrepen?</h3><p>Bij Sky XL dp_1010 noemt de winkel een plafondbevestiging, maar ook dat die niet inbegrepen is. Bij Whipped XL dp_1017 staat eveneens inclusief plafondbevestiging tegenover fitting of stekkerkabel niet inbegrepen. Bij Dome XL dp_1013 staat plafondbevestiging inbegrepen. Bevestig per uitvoering wat je krijgt voordat je bestelt. Vorm, handwerk en sfeer zeggen niets over gemeten leeslicht; daarvoor zijn onder meer lumen en de gekozen lichtbron nodig. De FTC legt het verschil tussen lumen en watt uit, maar test deze lampen niet.</p><p><a href="/grote-hanglamp">Vergelijk afmetingen, gewicht en ophanghoogte in de bestaande hanglampgids</a>. Controleer draagkracht en installatie-instructie; vraag een vakman als bevestiging onzeker is. Geen garantie dat een onbekende fitting of dimmer past.</p><h3>Babybedbumpers: hetzelfde categorieadvies voor nieuwe varianten</h3><p>Het afraadadvies voor het babybed geldt ook voor andere duidelijk genoemde bedbumpers. De NIH-voorlichting ondersteunt geen letselpreventieclaim; zachte bumpers kunnen verstikkings- en beknellingsrisico toevoegen. Dit is categorieadvies, geen modeltest of Nederlandse verbodsclaim. De twee gecontroleerde grijze Jersey en natuurlijke XL-varianten leveren volgens de winkel alleen naar Duitsland. Bij de natuurlijke XL noemt de titel 300 cm en de specificatie circa 200 cm: maat eerst bevestigen. Andere varianten krijgen geen veronderstelde landbeperking.</p><p>Winkelbronnen: <a href="https://kadoly.com/product/dp_1004?lang=nl">Nina</a>, <a href="https://kadoly.com/product/dp_1007?lang=nl">Lauren</a>, <a href="https://kadoly.com/product/dp_1010?lang=nl">Sky XL</a>, <a href="https://kadoly.com/product/dp_1013?lang=nl">Dome XL</a>, <a href="https://kadoly.com/product/dp_1017?lang=nl">Whipped XL</a>, <a href="https://kadoly.com/product/oc_4174005519319041?lang=nl">grijze Jersey-bedbumper</a>, <a href="https://kadoly.com/product/oc_4174005539094529?lang=nl">natuurlijke XL-bedbumper</a>.</p>'+bronnenHtml(['servies','lichtFtc','babyNih'])+'</section>';
}
function meubels20() {
 return '<section id="meubels-20nov"><h2>Zware meubels: eerst variant, doosinhoud en bezorging bevestigen</h2><p class="meta">Winkelpagina’s gecontroleerd 20 november 2026. Kadoly is de verkoper. De volgende gegevens zijn makeropgaven, geen onafhankelijke materiaal-, sterkte- of gebruikstest.</p><div style="overflow:auto"><table><thead><tr><th>Model</th><th>Wat de winkel opgeeft</th><th>Eerst bevestigen</th></tr></thead><tbody><tr><th><a href="https://kadoly.com/product/dp_1021?lang=nl">Oxford eettafel</a></th><td>Acacia met acaciafineer; 76 × 183/241 × 99 cm; 129 kg.</td><td>Welke lengte en uitvoering krijg je? Is de verlenging inbegrepen? De beschrijving noemt ook handgrepen, wat niet vanzelfsprekend bij deze tafel past. Gewicht bewijst geen duurzaamheid.</td></tr><tr><th><a href="https://kadoly.com/product/dp_1027?lang=nl">Winston ronde eettafel</a></th><td>Gesinterd steen; diameter 119 cm. De tekst beschrijft ook velvet stoelen.</td><td>De titel verkoopt een tafel, de tekst spreekt over een eetset. Aantal meegeleverde stoelen is niet bevestigd. Hitte- en krasbestendigheid zijn ongetoetste makerclaims.</td></tr><tr><th><a href="https://kadoly.com/product/dp_1035?lang=nl">Tanner platformbed</a></th><td>180 × 200 cm in de titel; buitenmaat 112 × 195 × 215 cm; essen en essenfineer; 98 kg.</td><td>Matras, lattenbodem, montage en passende matrasmaat afzonderlijk bevestigen. De titelmaat is niet de buitenmaat; verschillende afwerkingsnamen bewijzen geen variantkeuze.</td></tr><tr><th><a href="https://kadoly.com/product/dp_1037?lang=nl">Tanner vierdeurs dressoir</a></th><td>79 × 163 × 46 cm; essen en essenfineer; 71 kg.</td><td>Montagehandleiding, verankeringsmateriaal en geschiktheid voor je wand opvragen. Een zwaar meubel is niet automatisch kantelveilig.</td></tr></tbody></table></div><p>De winkel vermeldt vrachtwagenbezorging. Dat bevestigt geen levering op een verdieping, montage, uitpakken of afvoer van verpakking. Meet deur, trap, lift en verpakkingsmaten; productmaten zijn geen doosmaten. Vraag deze afspraken en eventuele kosten schriftelijk vóór aankoop na. Bij onduidelijke variant of ongeschikte toegangsroute: wacht met bestellen.</p><p>CPSC adviseert topzware meubels te verankeren en de montage-instructie te volgen. Dit algemene advies is geen vastgestelde onveiligheid van Tanner en geen claim dat een Amerikaanse wettelijke norm hier van toepassing is.</p>'+bronnenHtml(['meubelCpsc'])+'<p>Een deel van deze producten stond al op 19 november in de gids, hoewel de winkel nu 20 november als catalogusdatum geeft. Dat is geen bewijs van een nieuwe introductie.</p></section>';
}
function kamado22() {
 return '<section id="kamado-22nov"><h2>Yakiniku Kamado 22 inch XL: welke uitvoering koop je?</h2><p class="meta">Winkelpagina en externe bronnen gecontroleerd 22 november 2026. Kadoly is de verkoper; geen eigen grilltest of onafhankelijke modelscore.</p><p><strong>Koop deze houtskoolbarbecue alleen voor een geschikte plek buiten.</strong> Gebruik hem niet in huis, garage, tent of een andere besloten ruimte. De fabrikant waarschuwt hiervoor; de GGD beschrijft rook, fijnstof en koolmonoxide bij houtskool. Ook buiten kan rook omwonenden hinderen. Wil je rook vermijden, overweeg dan elektrisch; dit is geen test waaruit blijkt dat deze kamado slecht presteert.</p><div style="overflow:auto"><table><thead><tr><th>Controle</th><th>Wat is bekend?</th><th>Wat eerst bevestigen?</th></tr></thead><tbody><tr><th>Materiaal en maat</th><td>Kadoly dp_1019 noemt keramiek/RVS, 76 × 76 × 96 cm en diameter 66 cm.</td><td>Dit zijn winkelopgaven. De buitendiameter is niet het grillrooster. De fabrikant noemt voor zijn XLARGE circa 56 cm rooster; neem die maat niet zonder artikelnummer over.</td></tr><tr><th>Uitvoering</th><td>De maker biedt verschillende XLARGE-sets. De basicpagina noemt onderstel en zijtafels.</td><td>Fabrikantartikelnummer, bouwjaar, onderstel, zijtafels, rooster en accessoires van de geleverde Kadoly-set. De huidige winkeltekst bevestigt die combinatie niet.</td></tr><tr><th>Prestaties</th><td>Warmtebehoud en nauwkeurige temperatuurcontrole zijn winkelclaims.</td><td>Geen onafhankelijke meetmethode, verbruiksvergelijking of duurzaamheidstest van dp_1019 ingezien. Keramiek of RVS alleen bewijst die prestaties niet.</td></tr><tr><th>Bezorging</th><td>De productpagina noemt bezorging met een vrachtwagen.</td><td>Afspraak, bereikbaarheid, losplek en hulp bij verplaatsen. Levering tot binnen of montage is niet bevestigd. Gebruik de actuele prijs en bezorgschatting in het aanbod hieronder; geen vaste voorraadbelofte.</td></tr></tbody></table></div><p>De handleiding verlangt juiste montage en een stabiele plek, uit de buurt van brandbare materialen. Vraag de instructie voor de exacte uitvoering op. Voor inpassen in een buitenkeuken of als de doosinhoud doorslaggevend is, stel aankoop uit tot artikelnummer en maten zijn bevestigd. Onbekend betekent niet bewezen onveilig of slechte kwaliteit.</p><p><a href="https://kadoly.com/product/dp_1019?lang=nl">Gecontroleerde winkelpagina</a> · <a href="/alle-producten#product-dp_1019">Actuele prijs en beschikbaarheid</a> · <a href="https://www.yakinikugrill.com/nl/handleidingen">Handleidingen van de maker</a>.</p><h3>Bronnen en belangen</h3>'+bronnenHtml(['kamadoGgd','kamadoMaker','kamadoManual'])+'</section>';
}
function instroom21() {
 return '<section id="instroom-21nov"><h2>Nieuwe varianten: slaapzak, schaal en woonproducten</h2><p class="meta">Winkelpagina’s en relevante voorlichting gecontroleerd 21 november 2026. Geen eigen gebruik of test; Kadoly is de verkoper.</p><h3>Mint babyslaapzak: alle seizoenen niet bevestigd</h3><p>De winkel noemt katoen, fleece, maten 60/70/90/110 cm en vier schouderdrukkers, maar geen TOG. Dat ondersteunt geen geschiktheid voor alle warme en koude nachten. VeiligheidNL adviseert passende hals- en armsgaten en een rits in plaats van knopen. De schouderdrukkers vragen dus expliciete aandacht; wil je deze keuze-instructie volgen, kies een passende uitvoering zonder die knopen. Vraag warmte- en pasvorminstructies op; ontbrekende TOG is geen zelfstandige kwaliteitsafkeuring. De productpagina levert deze mintvariant alleen naar Duitsland, niet Nederland.</p><p><a href="https://kadoly.com/product/baby-schlafsack-mint?lang=nl">Gecontroleerde mintvariant</a>. Nieuwe duidelijk genoemde babyslaapzakken lopen mee in de algemene pasvorm-/warmtecheck, maar krijgen geen veronderstelde landbeperking of ontbrekende eigenschap toegewezen.</p>'+bronnenHtml(['babySlaapzak'])+'<h3>Bowlzilla: schaal is geen voedselcontactbewijs</h3><p>De winkel noemt massief hout voor fruit, kaarsen en decoratie. Coating-, voedselcontact- en reinigingsinstructies zijn niet vastgesteld. Gebruik hem niet voor heet, nat of onverpakt eten zonder bevestiging van het bedoelde gebruik. Massief hout bewijst geen veiligheid of onveiligheid. De NVWA adviseert het etiket en de gebruiksinstructie te volgen. Kaarsen noemen in een producttekst bewijst evenmin dat direct brandend gebruik op hout veilig is.</p>'+bronnenHtml(['servies'])+'<h3>Vier woonartikelen die geen keukenglas zijn</h3><ul><li>Garaffa dp_1091 is een rieten hanglamp van 70 × 30 × 30 cm met E27-optie; elektrische componenten en montagematerialen zijn volgens de winkel niet inbegrepen.</li><li>Marilyn dp_1160 is een consoletafel van 74 × 132 × 41 cm en 21 kg. Montage is nodig; gereedschap niet inbegrepen. RVS, gehard glas en acryl zijn makeropgaven, geen duurzaamheidstest.</li><li>Het Bagagerek dp_1187 is teakhouten bagageopslag, geen servies. Draagvermogen en volledige maatvoering niet bevestigd in de gecontroleerde tekst; niet als zitmeubel adviseren.</li><li>Jasmijnbord dp_1074 is rieten wandkunst van 60 × 60 × 5 cm, geen eetbord. Daarom geen automatische serviesgoedkeuring.</li></ul><p>Winkelbronnen: <a href="https://kadoly.com/product/dp_1222?lang=nl">Bowlzilla</a>, <a href="https://kadoly.com/product/dp_1091?lang=nl">Garaffa</a>, <a href="https://kadoly.com/product/dp_1160?lang=nl">Marilyn</a>, <a href="https://kadoly.com/product/dp_1187?lang=nl">bagagerek</a>, <a href="https://kadoly.com/product/dp_1074?lang=nl">Jasmijnbord</a>.</p><p>Duidelijke woonproducten worden in de gids opnieuw ingedeeld; dit verandert de winkelbron niet en bewijst geen kwaliteit.</p></section>';
}
export function onderzoekHub(items) { const d = dekking(items); return `<p class="kicker">Onze werkwijze</p><h1>Onderzoek, bronnen en eerlijke koopchecks</h1><div class="answer"><p>${d.metCategorieAdvies} van ${d.totaal} beschikbare producten vallen onder een van onze ${ONDERZOEK.length} koopchecks. Dat is categorieadvies. <strong>Geen van deze producten is door ons onafhankelijk getest.</strong></p></div><p>Kadoly verkoopt de producten en is daarmee geen onafhankelijke testorganisatie. We zoeken ook bewijs dat een verkoopclaim tegenspreekt. We onderscheiden productfeiten van de maker, extern onderzoek, ons advies en wat onbekend blijft. Een bron over materiaal of een categorie is nooit een certificaat voor een product.</p>${kamado22()}${instroom21()}${meubels20()}${instroom19(items)}${nieuwProductBronnen(items)}<h2>Kies een onderwerp</h2><dl class="rows">${d.onderwerpen.map(p => `<div class="r"><dt><a href="/onderzoek-${p.id}">${e(p.titel)}</a></dt><dd>${p.producten} producten met een passende koopcheck.</dd></div>`).join('')}</dl><h2>Wanneer we een product afraden</h2><p>Als het aantoonbaar niet past bij het gebruik, of als je een eigenschap nodig hebt die niet bevestigd is. Een onbekende prestatie krijgt geen verzonnen cijfer. Positieve en negatieve resultaten, beperkingen en bekende commerciële financiering staan bij de bron.</p><h2>Hoe we onze inhoud verbeteren</h2><p>We volgen welke vragen lezers stellen en welke onderwerpen in zoekmachines worden gevonden. Populariteit is geen bewijs van kwaliteit. Verkoop verandert de onderzoeksconclusie niet. Nieuwe productgegevens of beter bewijs kunnen het advies wel veranderen.</p><p class="meta">Bronlaag inhoudelijk bijgewerkt op <time datetime="${ONDERZOEK_DAG}">${ONDERZOEK_DAG}</time>. De controledatum staat per bron vermeld. Prijzen en beschikbaarheid komen uit de actuele winkelcatalogus.</p>`; }
export function onderzoekPagina(p, items, prijs, datum) { const lijst = items.filter(i => i.vr !== false && p.match(i)).sort((a,b) => String(a.t).localeCompare(String(b.t), 'nl')); return `<nav class="crumbs"><a href="/">Kadoly gids</a> › <a href="/onderzoek-en-bronnen">Onderzoek en bronnen</a></nav><p class="kicker">Onderbouwd kiezen</p><h1>${e(p.titel)}</h1><p class="meta">Kadoly redactie · inhoud bijgewerkt <time datetime="${onderwerpDag(p)}">${onderwerpDag(p)}</time> · geen eigen producttest</p><div class="answer"><p>${e(p.kort)}</p></div><h2>Welke claim toetsen we?</h2><p>${e(p.claim)}</p><h2>Wat ondersteunt de bron?</h2><p>${e(p.bewijs)}</p><h2>Wat bewijst dit niet?</h2><p>${e(p.nuance)}</p><h2>Ons koopadvies</h2><p>${e(p.advies)}</p><ul>${p.check.map(x=>`<li>${e(x)}</li>`).join('')}</ul><h2>Bronnen en belangen</h2>${bronnenHtml(p.bronnen)}<p>We zijn de verkoper. We hebben geen van de onderstaande modellen zelf getest. De externe auteurs hebben deze Kadoly-selectie niet beoordeeld of aanbevolen.</p>${p.gidsen.length ? `<h2>Verder kiezen</h2><ul>${p.gidsen.map(g=>`<li><a href="/${g}">${e(g.replace(/-/g,' '))}</a></li>`).join('')}</ul>` : ''}<h2>Bij welke producten is deze check relevant?</h2><p>${lijst.length} beschikbare producten. De koppeling volgt de productnaam in de winkelcatalogus; zij bevestigt geen materiaal- of prestatieclaim. Controleer de volledige productspecificatie vóór aankoop.</p><div class="br-producten">${lijst.map(i=>`<article id="p-${e(i.id)}"><h3><a href="/naar/${e(i.id)}?g=onderzoek-${p.id}&amp;b=onderzoek" rel="nofollow">${e(i.t)}</a></h3><p>${e(i.b || 'Maker niet vermeld')} · ${prijs(i)} inclusief btw en verzending${i.lt ? ' · verwacht ' + e(datum(i.lt)) : ''}</p>${productFeit(i)}<p><b>Voor dit product controleren:</b> ${e(p.check.join(' '))}</p></article>`).join('')}</div><p><a href="/onderzoek-en-bronnen">Alle onderwerpen en onze werkwijze</a></p>`; }
export function onderzoekTekst(items) { let t = '\n## Onderzoek en bronnen\n\nhttps://gids.kadoly.com/onderzoek-en-bronnen\n\nKadoly is de verkoper. Externe categoriebronnen zijn geen tests van afzonderlijke producten. Geen eigen producttests. Versie bronlaag: ' + ONDERZOEK_DAG + '.\n\n'; for (const p of ONDERZOEK) { t += '### ' + p.titel + '\n\nhttps://gids.kadoly.com/onderzoek-' + p.id + '\n\n' + p.kort + '\n' + p.bewijs + '\nBeperking: ' + p.nuance + '\nAdvies: ' + p.advies + '\n'; for (const id of p.bronnen) {const b=BRONNEN[id];t += '- Bron: ' + b.organisatie + ', ' + b.soort + '. ' + b.url + '. ' + b.grens + '\n';} t += 'Toepasselijke producten: ' + items.filter(i=>i.vr!==false&&p.match(i)).length + '.\n\n';} t += '\n## Nieuwe productchecks\n\nhttps://gids.kadoly.com/onderzoek-en-bronnen#nieuw-productadvies\n\n' + (kamado22()+instroom21()+meubels20()+instroom19(items)+nieuwProductBronnen(items)).replace(/<a href="([^"]+)"[^>]*>(.*?)<\/a>/g, '$2 ($1)').replace(/<[^>]*>/g, ' ').replace(/ +/g, ' ') + '\n'; return t; }








